<?php/*Plugin Name: OK Q&A Expert Engine (Admin Style)Description: Q&A სისტემა, რომელიც მენიუს ამატებს init_profile_tabs ჰუკის გამოყენებით. SweetAlert2 ვიზუალი განახლებულია.Version: 23.0Author: OK Engine Team*/if (!defined('OK_LOADED')) exit;// 1. დირექტორიის დაფიქსირებაif (!defined('OK_QA_PATH')) {    define('OK_QA_PATH', __DIR__);}// -------------------------------------------------------------------------// მენიუს დამატება (INTEGRATION)// -------------------------------------------------------------------------add_ok_action('init_profile_tabs', function() {        // ვამოწმებთ, რომ პროფილის სისტემა მზად არის მიიღოს ტაბი    if (function_exists('add_ok_profile_tab')) {                add_ok_profile_tab(            'qa-expert',                 // Slug (უნიკალური ID URL-ისთვის)            'ექსპერტის პანელი',          // სათაური            'bi-chat-left-text-fill',    // აიკონი            function($user) {            // ფუნქცია, რომელიც იხატება მარჯვენა მხარეს                                // აქ ვიძახებთ Dashboard-ს                if (function_exists('ok_qa_expert_dashboard_shortcode')) {                    echo ok_qa_expert_dashboard_shortcode(['uid' => $user->id]);                } else {                    echo "QA სისტემა ვერ ჩაიტვირთა.";                }            },            15 // რიგითობა (პარამეტრების შემდეგ)        );    }});// -------------------------------------------------------------------------// ბაზის ინსტალაცია// -------------------------------------------------------------------------add_ok_action('admin_menu', function() {    global $ok_db;        $ok_db->query("CREATE TABLE IF NOT EXISTS ok_qa_experts (        id INT AUTO_INCREMENT PRIMARY KEY, uid INT, expert_slug VARCHAR(50) UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;");    $ok_db->query("CREATE TABLE IF NOT EXISTS ok_qa_questions (        id INT AUTO_INCREMENT PRIMARY KEY, expert_id INT, user_name VARCHAR(100), user_email VARCHAR(100),        question_text TEXT, answer_text TEXT, status ENUM('pending', 'published') DEFAULT 'pending',        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX (expert_id), INDEX (status)    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;");    add_menu_page('Q&A სისტემა', 'Q&A სისტემა', 'manage_options', 'ok-qa-list', 'ok_qa_main_gui', 'bi bi-chat-dots', 40);    add_submenu_page('ok-qa-list', 'კითხვები', 'კითხვები', 'manage_options', 'ok-qa-list', 'ok_qa_main_gui');    add_submenu_page('ok-qa-list', 'ექსპერტები', 'ექსპერტები', 'manage_options', 'ok-qa-experts', 'ok_qa_experts_gui');});// -------------------------------------------------------------------------// EXPERT DASHBOARD LOGIC (ვიზუალი განახლებულია)// -------------------------------------------------------------------------function ok_qa_expert_dashboard_shortcode($atts) {    global $ok_db;    if (session_status() == PHP_SESSION_NONE) session_start();    $defaults = ['uid' => 0];    $atts = (array)$atts;     $a = array_merge($defaults, $atts);     $uid = (int)$a['uid'];    // ავტომატური აღქმა    if ($uid === 0 && isset($_SESSION['ok_cab_user']['id'])) $uid = (int)$_SESSION['ok_cab_user']['id']; // ძველი სესია    if ($uid === 0 && isset($_SESSION['user_id'])) $uid = (int)$_SESSION['user_id']; // ახალი სესია    // ექსპერტის შემოწმება    $expert = $ok_db->get_row("SELECT id, expert_slug FROM ok_qa_experts WHERE uid = ?", [$uid], PDO::FETCH_ASSOC);    if (!$expert) {        return '<div class="alert alert-warning p-4 rounded-3 text-center">                    <i class="bi bi-shield-lock fs-1 mb-3 d-block text-warning"></i>                    თქვენ არ გაქვთ ექსპერტის პანელზე წვდომა.                </div>';    }    $expert_id = $expert['id'];    $output = '';    // პასუხის გაცემა (PHP დამუშავება)    if (isset($_POST['save_frontend_answer']) && isset($_POST['q_id'])) {        $q_id = (int)$_POST['q_id'];        $answer_text = $_POST['frontend_answer_text'];        $check_q = $ok_db->get_row("SELECT * FROM ok_qa_questions WHERE id = ? AND expert_id = ?", [$q_id, $expert_id], PDO::FETCH_ASSOC);        if ($check_q) {            $ok_db->query("UPDATE ok_qa_questions SET answer_text = ?, status = 'published' WHERE id = ?", [$answer_text, $q_id]);                        // მეილის გაგზავნა            if (function_exists('ok_mail') && !empty($check_q['user_email'])) {                ok_mail($check_q['user_email'], "პასუხი შეკითხვაზე", strip_tags($answer_text));            }                        // ნოთიფიკაცია            if (function_exists('ok_add_notification')) {                $u_id_fetch = $ok_db->get_var("SELECT id FROM ok_users WHERE email = ?", [$check_q['user_email']]);                if ($u_id_fetch) ok_add_notification("თქვენს კითხვაზე პასუხი გაცემულია!", 'success', [(int)$u_id_fetch], "/", 0);            }                        $output .= '<script>                document.addEventListener("DOMContentLoaded", function(){                     Swal.fire({                        icon: "success",                        title: "წარმატება!",                        text: "პასუხი წარმატებით გაიგზავნა.",                        confirmButtonColor: "#0d6efd"                    });                 });            </script>';        }    }    // კითხვების სია    $questions = $ok_db->get_results("SELECT * FROM ok_qa_questions WHERE expert_id = ? ORDER BY status ASC, created_at DESC", [$expert_id], PDO::FETCH_ASSOC);    ob_start();    ?>    <script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>        <div class="ok-qa-dashboard">        <div class="d-flex justify-content-between align-items-center mb-4 border-bottom pb-3">            <h4 class="m-0 text-primary"><i class="bi bi-briefcase-fill"></i> ექსპერტის კაბინეტი</h4>            <span class="badge bg-light text-dark border">ID: <?php echo $uid; ?></span>        </div>        <?php if (empty($questions)): ?>            <div class="alert alert-info text-center py-5">                <i class="bi bi-inbox fs-1 opacity-50 mb-3 d-block"></i>                ჯერ კითხვები არ შემოსულა.            </div>        <?php else: ?>            <div class="table-responsive">                <table class="table table-hover align-middle bg-white border rounded">                    <thead class="table-light text-uppercase small text-muted">                        <tr>                            <th scope="col">ავტორი</th>                            <th scope="col">კითხვა</th>                            <th scope="col" class="text-center">სტატუსი</th>                            <th scope="col">მოქმედება</th>                        </tr>                    </thead>                    <tbody>                        <?php foreach ($questions as $q): ?>                            <tr>                                <td>                                    <div class="fw-bold"><?php echo htmlspecialchars($q['user_name']); ?></div>                                    <small class="text-muted" style="font-size: 0.75rem;"><i class="bi bi-clock"></i> <?php echo date('d M, H:i', strtotime($q['created_at'])); ?></small>                                </td>                                <td>                                    <div class="text-break" style="max-width: 400px;">                                        <?php echo mb_strimwidth(nl2br(htmlspecialchars($q['question_text'])), 0, 100, "..."); ?>                                    </div>                                </td>                                <td class="text-center">                                    <?php echo ($q['status']=='pending')                                         ? '<span class="badge bg-warning text-dark"><i class="bi bi-hourglass-split"></i> ახალი</span>'                                         : '<span class="badge bg-success"><i class="bi bi-check2-circle"></i> უპასუხა</span>';                                     ?>                                </td>                                <td class="text-end">                                    <button class="btn btn-sm btn-primary shadow-sm"                                             onclick="openQA_Modal(                                                <?php echo $q['id']; ?>,                                                 '<?php echo htmlspecialchars($q['user_name'], ENT_QUOTES); ?>',                                                 '<?php echo str_replace(["\r", "\n"], " ", htmlspecialchars($q['question_text'], ENT_QUOTES)); ?>',                                                 '<?php echo str_replace(["\r", "\n"], "\\n", htmlspecialchars($q['answer_text']??'', ENT_QUOTES)); ?>'                                            )">                                        <i class="bi bi-pencil-square"></i> პასუხი                                    </button>                                </td>                            </tr>                        <?php endforeach; ?>                    </tbody>                </table>            </div>        <?php endif; ?>    </div>    <script>    function openQA_Modal(id, user, question, currentAnswer) {        Swal.fire({            title: 'პასუხის გაცემა',            width: 650, // უფრო განიერი მოდალი            html: `                <div class="text-start">                    <div class="mb-3 p-3 bg-light border rounded">                        <div class="d-flex justify-content-between align-items-center mb-2 border-bottom pb-1">                            <span class="badge bg-secondary">ავტორი: ${user}</span>                        </div>                        <div class="text-dark fst-italic">                            "${question}"                        </div>                    </div>                                        <div class="form-group text-start">                        <label class="form-label fw-bold small text-uppercase text-muted">თქვენი პასუხი:</label>                        <textarea id="swal-input-answer" class="form-control" rows="6" placeholder="დაწერეთ პასუხი აქ...">${currentAnswer}</textarea>                    </div>                </div>            `,            showCancelButton: true,            confirmButtonText: '<i class="bi bi-send-fill"></i> გაგზავნა',            cancelButtonText: 'დახურვა',            confirmButtonColor: '#0d6efd',            cancelButtonColor: '#6c757d',            focusConfirm: false,            preConfirm: () => {                const answer = document.getElementById('swal-input-answer').value;                if (!answer) {                    Swal.showValidationMessage('გთხოვთ ჩაწეროთ პასუხი');                }                return answer;            }        }).then((result) => {            if (result.isConfirmed) {                // ფორმის დინამიური შექმნა და გაგზავნა                let f = document.createElement('form');                 f.method = 'POST';                 f.style.display = 'none';                                f.innerHTML = `                    <input name="q_id" value="${id}">                    <input name="frontend_answer_text" value="${result.value.replace(/"/g, '&quot;')}">                    <input name="save_frontend_answer" value="1">                `;                                document.body.appendChild(f);                 f.submit();            }        });    }    </script>    <?php    $output .= ob_get_clean();    return $output;}// -------------------------------------------------------------------------// სხვა ფუნქციები (Admin & Render)// -------------------------------------------------------------------------function ok_qa_experts_gui() {    global $ok_db;    if (isset($_POST['link_user'])) {        $u_id = (int)$_POST['user_id'];        $slug = strtolower(str_replace([' ', '@', '.'], '-', $ok_db->get_row("SELECT username FROM ok_users WHERE id = ?", [$u_id], PDO::FETCH_ASSOC)['username']));        if(!$ok_db->get_var("SELECT count(*) FROM ok_qa_experts WHERE uid = ?", [$u_id])) {            $ok_db->query("INSERT INTO ok_qa_experts (uid, expert_slug) VALUES (?, ?)", [$u_id, $slug]);            echo '<div class="alert alert-success m-3">ექსპერტი დაემატა!</div>';        }    }    $experts = $ok_db->get_results("SELECT e.*, u.username, u.email FROM ok_qa_experts e JOIN ok_users u ON e.uid = u.id", [], PDO::FETCH_ASSOC);    $all_users = $ok_db->get_results("SELECT id, username, email FROM ok_users ORDER BY id DESC LIMIT 50", [], PDO::FETCH_ASSOC);    echo '<div class="p-4 bg-white"><h3>Q&A ექსპერტები</h3><div class="row g-4"><div class="col-md-4"><div class="card p-4"><form method="post"><label class="mb-2">მომხმარებლის მიბმა</label><select name="user_id" class="form-select mb-3" required><option value="">-- აირჩიეთ --</option>';    foreach($all_users as $u) echo '<option value="'.$u['id'].'">'.$u['username'].' ('.$u['email'].')</option>';    echo '</select><button name="link_user" class="btn btn-primary w-100">დამატება</button></form></div></div><div class="col-md-8"><table class="table"><thead><tr><th>ექსპერტი</th><th>შორთკოდი</th></tr></thead><tbody>';    if($experts) foreach($experts as $ex) echo '<tr><td>'.$ex['username'].'</td><td><code>[questionanswer slug="'.$ex['expert_slug'].'"]</code></td></tr>';    echo '</tbody></table></div></div></div>';}function ok_qa_main_gui() {    global $ok_db;    $id = (int)($_GET['id'] ?? 0);    if (isset($_POST['save_answer'])) {        $answer = $_POST['answer_text'];         $ok_db->query("UPDATE ok_qa_questions SET answer_text = ?, status = 'published' WHERE id = ?", [$answer, $id]);        $q_data = $ok_db->get_row("SELECT * FROM ok_qa_questions WHERE id = ?", [$id], PDO::FETCH_ASSOC);        if ($q_data && function_exists('ok_mail')) ok_mail($q_data['user_email'], "პასუხი", strip_tags($answer));        echo "<script>window.location.href='?page=ok-qa-list&msg=answered';</script>"; exit;    }    $questions = $ok_db->get_results("SELECT q.*, u.username as expert_name FROM ok_qa_questions q JOIN ok_qa_experts e ON q.expert_id = e.id JOIN ok_users u ON e.uid = u.id ORDER BY q.status ASC, q.created_at DESC", [], PDO::FETCH_ASSOC);    echo '<div class="p-4 bg-white"><h3>შემოსული შეკითხვები</h3>';    if(isset($_GET['action']) && $_GET['action'] == 'edit') {        $curr = $ok_db->get_row("SELECT * FROM ok_qa_questions WHERE id = ?", [$id], PDO::FETCH_ASSOC);        echo '<div class="card p-4"><p><strong>კითხვა:</strong> '.htmlspecialchars($curr['question_text']).'</p><form method="post"><label>პასუხი:</label><textarea name="answer_text" class="form-control mb-3" rows="5">'.htmlspecialchars($curr['answer_text']).'</textarea><button name="save_answer" class="btn btn-success">გამოქვეყნება</button></form></div>';    } else {        echo '<table class="table"><thead><tr><th>ექსპერტი</th><th>ავტორი</th><th>კითხვა</th><th>სტატუსი</th><th></th></tr></thead><tbody>';        if($questions) foreach($questions as $q) {            echo '<tr><td>'.$q['expert_name'].'</td><td>'.$q['user_name'].'</td><td>'.mb_strimwidth($q['question_text'], 0, 50, "...").'</td><td>'.$q['status'].'</td><td><a href="?page=ok-qa-list&action=edit&id='.$q['id'].'" class="btn btn-sm btn-dark">პასუხი</a></td></tr>';        }        echo '</tbody></table>';    }    echo '</div>';}function ok_qa_render($atts) {    global $ok_db;    $atts = (array)$atts; $slug = isset($atts['slug']) ? trim($atts['slug']) : '';    if (empty($slug)) return '<div class="alert alert-warning">Error: Slug not defined.</div>';    $expert = $ok_db->get_row("SELECT e.id, e.uid, u.username, u.email FROM ok_qa_experts e JOIN ok_users u ON e.uid = u.id WHERE e.expert_slug = ?", [$slug], PDO::FETCH_ASSOC);    if (!$expert) return '<div class="alert alert-danger">Expert not found.</div>';    ob_start();     ?>    <div class="ok-qa-wrapper my-4">        <h5>დასვით კითხვა</h5>        <?php        if (isset($_POST['ok_send_qa']) && (int)$_POST['ex_id'] === (int)$expert['id']) {            $u_name = strip_tags($_POST['u_name']); $u_text = strip_tags($_POST['u_text']); $u_email = strip_tags($_POST['u_email']);            $ok_db->query("INSERT INTO ok_qa_questions (expert_id, user_name, user_email, question_text) VALUES (?, ?, ?, ?)", [$expert['id'], $u_name, $u_email, $u_text]);            if (function_exists('ok_mail')) ok_mail($expert['email'], "ახალი კითხვა", $u_text);            echo '<div class="alert alert-success">✅ გაიგზავნა!</div>';        }        ?>        <form method="post" class="mb-5 p-4 bg-light border rounded">            <input type="hidden" name="ex_id" value="<?php echo $expert['id']; ?>">            <div class="row g-3">                <div class="col-md-6"><input type="text" name="u_name" class="form-control" placeholder="სახელი" required></div>                <div class="col-md-6"><input type="email" name="u_email" class="form-control" placeholder="ელ-ფოსტა" required></div>                <div class="col-12"><textarea name="u_text" class="form-control" rows="3" placeholder="კითხვა" required></textarea></div>                <div class="col-12"><button name="ok_send_qa" class="btn btn-primary">გაგზავნა</button></div>            </div>        </form>        <?php $answers = $ok_db->get_results("SELECT * FROM ok_qa_questions WHERE expert_id = ? AND status = 'published' ORDER BY created_at DESC", [$expert['id']], PDO::FETCH_ASSOC); ?>        <div class="qa-feed">            <?php if($answers): foreach($answers as $it): ?>                <div class="mb-3 border p-3 rounded bg-white">                    <div class="fw-bold mb-2"><i class="bi bi-question-circle"></i> <?php echo htmlspecialchars($it['question_text']); ?></div>                    <div class="ps-3 border-start border-3 border-primary text-muted"><?php echo nl2br($it['answer_text']); ?></div>                </div>            <?php endforeach; endif; ?>        </div>    </div>    <?php return ob_get_clean(); }// რეგისტრაციაif (function_exists('add_ok_shortcode')) {     add_ok_shortcode('questionanswer', 'ok_qa_render');     add_ok_shortcode('ok_expert_dashboard', 'ok_qa_expert_dashboard_shortcode'); }?>